export interface Encounter {
  id: string;
  createdAt: number;
}

export interface MonsterInstance {
  id: string;
  encounterId: string;
  monsterKey: string;
  displayName: string;
  maxHp: number;
  currentHp: number;
  initiative: number | null;
  groupId: string | null;
  createdAt: number;
}

/** id, currentHp (starts at maxHp) and createdAt are generated by the store. */
export interface NewMonsterInstance {
  monsterKey: string;
  displayName: string;
  maxHp: number;
  initiative?: number | null;
  groupId?: string | null;
}
